cd /app && cat > /tmp/final_check.test.ts <<'EOF'
import { format as originalFormat, FormatFn } from '../src/sqlFormatter.js';
const format: FormatFn = (q, c = {}) => originalFormat(q, { ...c, language: 'bigquery' });
test('final', () => {
  console.log(format(`FROM users
  |> WHERE active = TRUE
  |> AGGREGATE COUNT(*) AS total GROUP BY country
  |> EXTEND total * 2 AS doubled
